ab38c4bb-496d-4dba-9f4e-a34f179b8cff	9d2a4701d478241e29b1105e2adb4dafa69f91db8cdb1a78fda97f65cba26a7d	# قفل حساب\n\nحالة السياسة: قواعد محاكاة لبنك افتراضي في مشروع تخرج، وليست سياسة بنك حقيقي أو متطلبات قانونية.\nالإصدار: 1.0. تاريخ إصدار المحاكاة: 2026-11-02.\n\n## قواعد الخدمة الافتراضية\nإغلاق الحساب أو قفل الحساب في البنك الافتراضي يتطلب تصفير الرصيد وتسوية الالتزامات وعدم وجود عمليات معلقة. وجود قرض قائم مرتبط بالحساب يمنع الإغلاق حتى تسويته.\n\nيطلب العميل إغلاق حسابه بعد التحقق من هويته وملكيته للحساب وتأكيد الطلب صراحة. لا يجوز إغلاق حساب شخص آخر.\n\nرسوم إغلاق الحساب 0 جنيه مصري. مدة إغلاق الحساب 3 أيام عمل بعد استيفاء الشروط وتأكيد الطلب.\n\nيمكن إلغاء طلب إغلاق الحساب قبل اكتمال تنفيذه دون رسوم. بعد الإغلاق لا يعاد تفعيل الحساب نفسه؛ يتطلب الرجوع تقديم طلب فتح حساب جديد.\n\nطلب إغلاق الحساب في محادثة RAG لا ينفذ الإغلاق ولا يسوي الرصيد أو الالتزامات.\n\n## حدود الاستخدام الحالي\nالاستفسار المحلي عن السياسات لا يحتاج تسجيل دخول. الوصول إلى بيانات عميل أو تنفيذ إجراء مستقبلي يحتاج التحقق من الهوية والصلاحيات في الخدمة المختصة. ملفات السياسات لا تحتوي بيانات عملاء أو صور بطاقات أو نتائج OCR.	{0.06493771756193205,0.016234429390483012,0,0.16234429390483013,0.008117214695241506,0.06493771756193205,0.032468858780966024,0.08117214695241506,0.024351644085724516,0.04058607347620753,0.016234429390483012,0.024351644085724516,0.04058607347620753,0.032468858780966024,0.05682050286669054,0,0.008117214695241506,0.016234429390483012,0.024351644085724516,0.008117214695241506,0.04058607347620753,0.016234429390483012,0.032468858780966024,0.008117214695241506,0,0.07305493225717355,0.08117214695241506,0.008117214695241506,0.06493771756193205,0,0.008117214695241506,0.008117214695241506,0.024351644085724516,0,0.016234429390483012,0.05682050286669054,0.04058607347620753,0.008117214695241506,0,0.008117214695241506,0.024351644085724516,0,0.08928936164765656,0,0,0.07305493225717355,0,0,0.04058607347620753,0.016234429390483012,0.032468858780966024,0,0.04870328817144903,0,0.032468858