c3ca59bf-7afa-447a-9967-2cb06b4a7db3	b9d5c492cec970e200b6ae32c5cc0896b76ce3a9bc56f1a7c1ac2a6963157648	# فتح حساب\n\nحالة السياسة: قواعد محاكاة لبنك افتراضي في مشروع تخرج، وليست سياسة بنك حقيقي أو متطلبات قانونية.\nالإصدار: 1.0. تاريخ إصدار المحاكاة: 2026-11-02.\n\n## قواعد الخدمة الافتراضية\nفتح الحساب في البنك الافتراضي متاح للأفراد من عمر 21 سنة فأكثر، بالجنيه المصري فقط، بنوع حساب جاري أو حساب توفير.\n\nالمستندات المطلوبة لفتح الحساب هي بطاقة رقم قومي سارية وإثبات عنوان ورقم هاتف يخص مقدم الطلب. التحقق من المستندات ومراجعة الطلب مطلوبان قبل التفعيل؛ قراءة البطاقة بالـOCR وحدها لا تثبت ملكية الهوية.\n\nرسوم فتح الحساب 0 جنيه مصري. الحد الأدنى للإيداع عند فتح الحساب 100 جنيه مصري، ويضاف إلى رصيد العميل وليس رسومًا.\n\nرسوم الصيانة الشهرية للحساب 0 جنيه مصري. حساب التوفير في النسخة الافتراضية لا يمنح عائدًا على الرصيد.\n\nمدة مراجعة طلب فتح الحساب يومان عمل بعد اكتمال المستندات. نقص المستندات يوقف احتساب المدة حتى استكمالها.\n\nيمكن إلغاء طلب فتح الحساب قبل تفعيله دون رسوم. رفع البطاقة أو السؤال عن فتح الحساب لا ينشئ حسابًا فعليًا.\n\n## حدود الاستخدام الحالي	{0.041671007622730606,0.041671007622730606,0.008334201524546121,0.033336806098184485,0.008334201524546121,0.041671007622730606,0.033336806098184485,0,0.008334201524546121,0.033336806098184485,0.008334201524546121,0.06667361219636897,0.10834461981909957,0,0.05000520914727673,0,0.025002604573638364,0,0,0,0.041671007622730606,0.016668403049092242,0,0.016668403049092242,0.016668403049092242,0.016668403049092242,0.08334201524546121,0.016668403049092242,0.041671007622730606,0,0.041671007622730606,0.033336806098184485,0.033336806098184485,0.025002604573638364,0.041671007622730606,0.025002604573638364,0,0,0.016668403049092242,0,0.016668403049092242,0.008334201524546121,0.008334201524546121,0.041671007622730606,0,0.07500781372091508,0.041671007622730606,0.008334201524546121,0,0.033336806098184485,0.016668403049092242,0.05000520914727673,0.05000520914727673,0,0.016668403049092242,0.016668403049092242,0.016668403049092242