9d7d3303-ab39-4201-80dd-062be69e17af	745457e099851cfdef8d8df6c02f96dc68ba854b0e8a60bc298edbf1b895262b	# كشف حساب\n\nحالة السياسة: قواعد محاكاة لبنك افتراضي في مشروع تخرج، وليست سياسة بنك حقيقي أو متطلبات قانونية.\nالإصدار: 1.0. تاريخ إصدار المحاكاة: 2026-11-02.\n\n## قواعد الخدمة الافتراضية\nكشف الحساب في البنك الافتراضي يعرض حركات الحساب والرصيد الافتتاحي والرصيد الختامي بالجنيه المصري خلال الفترة المطلوبة.\n\nالفترة الافتراضية لكشف الحساب آخر 30 يومًا. يمكن طلب فترة حتى 12 شهرًا سابقة، بشرط ألا تبدأ قبل تاريخ فتح الحساب.\n\nكشف الحساب متاح بصيغتي PDF وCSV للتنزيل داخل الجلسة المصرح بها. رسوم كشف الحساب الإلكتروني 0 جنيه مصري. لا تتضمن النسخة الافتراضية كشفًا ورقيًا مختومًا أو إرسالًا بالبريد الإلكتروني.\n\nيُعد كشف الحساب عند الطلب من السجلات المتاحة دون مدة تسليم مضمونة. عند عدم توفر السجلات، تظهر رسالة عدم توفر البيانات ولا ينشأ كشف تخميني.\n\nلا يعرض كشف الحساب إلا لصاحب الحساب بعد تسجيل الدخول والتحقق من الصلاحيات. RAG يشرح سياسة كشف الحساب ولا يستطيع قراءة رصيدك أو إنشاء كشف معاملات حقيقي.\n\n## حدود الاستخدام الحالي\nالاستفسار المحلي عن السياسات لا يحتاج تسجيل دخول.	{0.03160303087599848,0.00790075771899962,0,0.02370227315699886,0.01580151543799924,0.07110681947099658,0.09480909262799544,0,0.03160303087599848,0.09480909262799544,0.00790075771899962,0.039503788594998104,0.03160303087599848,0,0.05530530403299734,0,0.01580151543799924,0,0.02370227315699886,0.08690833490899583,0.039503788594998104,0.02370227315699886,0,0.03160303087599848,0.02370227315699886,0.04740454631399772,0.02370227315699886,0.039503788594998104,0.03160303087599848,0,0.02370227315699886,0.01580151543799924,0.039503788594998104,0.01580151543799924,0,0.00790075771899962,0.039503788594998104,0,0,0,0,0,0.00790075771899962,0.039503788594998104,0,0.09480909262799544,0,0,0.00790075771899962,0.01580151543799924,0.00790075771899962,0.00790075771899962,0.10270985034699506,0.03160303087599848,0,0.039503788594998104,0.00790075771899962,0.04740454631399772,0.1185113657849943,0.02370227315699886,0,0.0079