517d0127-0012-4049-9e91-efa339ed5025	a5af3dcdbe9978b9b9f00d3d2927df46dfb37e5303dba878a515de3b80e080e2	هذه رسوم الاستعلام فقط؛ رسوم تنفيذ الإيداع النقدي غير محددة في نطاق المشروع.\n\nعرض عمليات الإيداع يتطلب تسجيل الدخول وملكية الحساب. عند عدم وجود عمليات تعرض قائمة فارغة. RAG لا يسترجع إيداعات العميل الفعلية ولا ينفذ إيداعًا.\n\n## حدود الاستخدام الحالي\nالاستفسار المحلي عن السياسات لا يحتاج تسجيل دخول. الوصول إلى بيانات عميل أو تنفيذ إجراء مستقبلي يحتاج التحقق من الهوية والصلاحيات في الخدمة المختصة. ملفات السياسات لا تحتوي بيانات عملاء أو صور بطاقات أو نتائج OCR.\n\nيوم العمل في هذه المحاكاة من الأحد إلى الخميس، باستثناء العطلات التي يحددها مشغل المشروع. مدد العمل أهداف للمحاكاة وليست تعهدات خدمة حقيقية.	{0.013065478400923492,0.013065478400923492,0,0,0.013065478400923492,0.05226191360369397,0.05226191360369397,0.013065478400923492,0.03919643520277048,0.09145834880646446,0.026130956801846985,0,0.013065478400923492,0,0,0,0.013065478400923492,0.10452382720738794,0.013065478400923492,0.026130956801846985,0,0.026130956801846985,0,0,0.026130956801846985,0.15678574081108193,0.05226191360369397,0,0,0.013065478400923492,0.026130956801846985,0,0,0.05226191360369397,0.03919643520277048,0.026130956801846985,0.11758930560831143,0,0,0,0.03919643520277048,0.013065478400923492,0.026130956801846985,0.026130956801846985,0,0,0,0,0.07839287040554097,0.013065478400923492,0.013065478400923492,0,0.013065478400923492,0.05226191360369397,0.026130956801846985,0.013065478400923492,0.013065478400923492,0,0.06532739200461747,0,0,0.03919643520277048,0,0.013065478400923492,0.05226191360369397,0.013065478400923492,0.026130956801846985,0.05226191360369397,0,0.05226191360369397,0.013065478400923492,0,0.07839287040554097,0.013065478400923492,0,0.013065478400923492,0,0.026130956801846985,0.05226191360369397,0,0,0.05226191360369397,0.013065478400923492,0,0,0,0.05226191360369397,0.013065478400923492,0.05226191360369397,0.05226191360369397,0,0,0.026130956801846985,0.05226191360369397,0.01306547840092349