259e8595-c482-48d3-a2dd-61d8bf9e9708	17498d7f921db38a1f2f3428007a444ee9c7a925834e8483bcbcb2ad6624096c	RAG يشرح سياسة الاستعلام عن السحوبات ولا يعرض سجل سحب شخصي ولا ينفذ سحبًا نقديًا.\n\n## حدود الاستخدام الحالي\nالاستفسار المحلي عن السياسات لا يحتاج تسجيل دخول. الوصول إلى بيانات عميل أو تنفيذ إجراء مستقبلي يحتاج التحقق من الهوية والصلاحيات في الخدمة المختصة. ملفات السياسات لا تحتوي بيانات عملاء أو صور بطاقات أو نتائج OCR.\n\nيوم العمل في هذه المحاكاة من الأحد إلى الخميس، باستثناء العطلات التي يحددها مشغل المشروع. مدد العمل أهداف للمحاكاة وليست تعهدات خدمة حقيقية.	{0.01610182790274746,0.01610182790274746,0,0,0,0.12881462322197967,0.06440731161098984,0,0.03220365580549492,0.09661096741648476,0.03220365580549492,0,0,0,0,0,0.01610182790274746,0.12881462322197967,0.01610182790274746,0.01610182790274746,0,0.01610182790274746,0,0,0.03220365580549492,0.14491645112472715,0.0805091395137373,0,0,0.01610182790274746,0.01610182790274746,0.01610182790274746,0,0,0,0.03220365580549492,0.14491645112472715,0,0,0,0.03220365580549492,0.01610182790274746,0.01610182790274746,0,0,0.01610182790274746,0,0,0.09661096741648476,0.01610182790274746,0,0,0.0805091395137373,0,0.04830548370824238,0.01610182790274746,0.01610182790274746,0,0.14491645112472715,0.01610182790274746,0,0.03220365580549492,0.01610182790274746,0.01610182790274746,0.0805091395137373,0,0.01610182790274746,0,0,0.06440731161098984,0.01610182790274746,0.01610182790274746,0.0805091395137373,0.01610182790274746,0,0.12881462322197967,0,0.01610182790274746,0.06440731161098984,0,0,0,0.01610182790274746,0,0,0,0.06440731161098984,0.01610182790274746,0.06440731161098984,0.06440731161098984,0,0,0.03220365580549492,0,0.01610182790274746,0,0,0,0,0.01610182790274746,0,0.01610182790274746,0.04830548370824238,0,0.03220365580549492,0.03220365580549492,0.06440731161098984,0,0.06440731161098984,0.03220365580549492,0.06440731161098984,0.0805091395137373,0,0.01610182790274746,0,0.01610182790274746,0,0,0.06440731161098984,0.01610182790274746,0.016